body:
await check('native headings and trigger/content relationships remain named',async()=>{assert.equal(await page.getByRole('heading',{name:'Alpha',exact:true}).count(),1);assert.equal(await page.getByRole('button',{name:'Alpha',exact:true}).getAttribute('aria-expanded'),'false');assert.equal(await page.locator('acme-accordion-trigger').first().evaluate(el=>el.shadowRoot.querySelector('button').ariaControlsElements[0]===el.closest('acme-accordion-item').querySelector('acme-accordion-content')),true);});
await check('single mode keeps one open and disallows closing the selected item',async()=>{await page.getByRole('button',{name:'Alpha',exact:true}).click();assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),['alpha']);assert.equal(await page.getByRole('button',{name:'Alpha',exact:true}).getAttribute('aria-disabled'),'true');await page.getByRole('button',{name:'Beta',exact:true}).click();assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),['beta']);});
await check('multiple mode allows independent opening and closing',async()=>{await page.locator('#accordion').evaluate(el=>el.multiple=true);await page.getByRole('button',{name:'Alpha',exact:true}).click();await page.getByRole('button',{name:'Beta',exact:true}).click();assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),['alpha','beta']);await page.getByRole('button',{name:'Alpha',exact:true}).click();assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),['beta']);});
await check('arrows and endpoints move focus without changing expansion',async()=>{await page.getByRole('button',{name:'Alpha',exact:true}).focus();await page.keyboard.press('ArrowDown');assert.equal(await page.getByRole('button',{name:'Beta',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);await page.keyboard.press('Home');assert.equal(await page.getByRole('button',{name:'Alpha',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),[]);});
await check('default content stays mounted while hidden and inert',async()=>{assert.equal(await page.locator('#alpha-input').count(),1);await page.getByRole('button',{name:'Alpha',exact:true}).click();await page.locator('#alpha-input').fill('Edited');await page.getByRole('button',{name:'Beta',exact:true}).click();assert.equal(await page.locator('#alpha-input').inputValue(),'Edited');assert.equal(await page.locator('acme-accordion-content').first().evaluate(el=>el.inert&&el.hidden),true);});
await check('controlled mounting creates and removes actual template children',async()=>{assert.equal(await page.locator('lifecycle-child').count(),0);await page.getByRole('button',{name:'More details',exact:true}).click();await page.waitForFunction(()=>document.querySelector('lifecycle-child'));assert.equal(await page.evaluate(()=>window.connected),1);await page.locator('#managed-input').fill('Edited');await page.getByRole('button',{name:'More details',exact:true}).click();await page.waitForFunction(()=>!document.querySelector('lifecycle-child'));assert.equal(await page.evaluate(()=>window.disconnected),1);await page.getByRole('button',{name:'More details',exact:true}).click();assert.equal(await page.locator('#managed-input').inputValue(),'Initial');});
await check('collapse recovers focus before making descendants inert',async()=>{await page.getByRole('button',{name:'Alpha',exact:true}).click();await page.locator('#alpha-input').focus();await page.locator('#accordion').evaluate(el=>el.expanded=[]);await page.waitForFunction(()=>document.querySelector('acme-accordion-trigger').shadowRoot.activeElement?.localName==='button');});
await check('root disability wins and programmatic state remains silent',async()=>{await page.locator('#accordion').evaluate(el=>{window.changes=0;el.addEventListener('acme-expanded-change',()=>window.changes++);el.disabled=true;el.expanded=['alpha']});await page.waitForFunction(()=>document.querySelector('acme-accordion-trigger').shadowRoot.querySelector('button').disabled);assert.equal(await page.evaluate(()=>window.changes),0);});
await check('disabled trigger collapse retains focus at its named section',async()=>{await page.getByRole('button',{name:'Alpha',exact:true}).click();await page.locator('#alpha-input').focus();await page.locator('#accordion').evaluate(el=>{el.disabled=true;el.expanded=[]});await page.waitForFunction(()=>document.activeElement?.localName==='acme-accordion-item');assert.equal(await page.locator('acme-accordion-item').first().evaluate(el=>el.ariaLabelledByElements?.[0]===el.querySelector('acme-accordion-trigger')),true);});
await check('Show removes inactive content and resets a remounted input',async()=>{assert.equal(await page.locator('#show-input').count(),0);await page.locator('#show').evaluate(el=>el.when=true);await page.locator('#show-input').fill('Edited');await page.locator('#show').evaluate(el=>el.when=false);await page.waitForFunction(()=>!document.querySelector('#show-input'));await page.locator('#show').evaluate(el=>el.when=true);assert.equal(await page.locator('#show-input').inputValue(),'Initial');});
await check('Show preservation retains nodes and blocks the inactive branch',async()=>{await page.locator('#show').evaluate(el=>{el.preserveState=true;el.when=true});await page.locator('#show-input').fill('Edited');await page.locator('#show').evaluate(el=>{window.retained=el.querySelector('input');el.when=false});await page.waitForFunction(()=>document.querySelector('#show').shadowRoot.querySelector('[part=content]').inert);await page.locator('#show').evaluate(el=>el.when=true);assert.equal(await page.locator('#show-input').inputValue(),'Edited');assert.equal(await page.evaluate(()=>window.retained===document.querySelector('#show-input')),true);});
await check('Show transfers departing focus to a fallback control',async()=>{await page.locator('#show').evaluate(el=>el.when=true);await page.locator('#show-input').focus();await page.locator('#show').evaluate(el=>el.when=false);await page.waitForFunction(()=>document.activeElement?.id==='fallback-button');});
await check('Show focuses its named branch when the fallback is empty',async()=>{await page.locator('#show').evaluate(el=>{el.querySelector('template[slot=fallback]').remove();el.when=true});await page.locator('#show-input').focus();await page.locator('#show').evaluate(el=>el.when=false);await page.waitForFunction(()=>document.querySelector('#show').shadowRoot.activeElement?.getAttribute('part')==='fallback');});
await check('Show More toggles once and blocks loading activation',async()=>{await page.locator('acme-show-more').evaluate(el=>{window.moreChanges=[];el.addEventListener('acme-expanded-change',e=>window.moreChanges.push(e.detail.expanded))});await page.getByRole('button',{name:'Show More',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.moreChanges),[true]);assert.equal(await page.getByRole('button',{name:'Show Less',exact:true}).getAttribute('aria-expanded'),'true');await page.locator('acme-show-more').evaluate(el=>{el.loading=true;el.expanded=false});await page.locator('acme-show-more').evaluate(el=>el.click());assert.deepEqual(await page.evaluate(()=>window.moreChanges),[true]);});
await check('Load More never submits and blocks repeat requests while loading',async()=>{await page.locator('acme-load-more').evaluate(el=>{window.requests=0;window.submits=0;el.closest('form').addEventListener('submit',e=>{e.preventDefault();window.submits++});el.addEventListener('acme-request',()=>{window.requests++;el.loading=true})});await page.getByRole('button',{name:'Load More',exact:true}).click();await page.locator('acme-load-more').evaluate(el=>el.click());assert.equal(await page.evaluate(()=>window.requests),1);assert.equal(await page.evaluate(()=>window.submits),0);});
await check('Tab Panel controlled lifetime still follows its selected tab',async()=>{await page.getByRole('tab',{name:'First tab',exact:true}).click();await page.locator('#first-panel-input').fill('Changed');await page.getByRole('tab',{name:'Second tab',exact:true}).click();await page.waitForFunction(()=>!document.querySelector('#first-panel-input')&&document.querySelector('#second-panel-input'));await page.getByRole('tab',{name:'First tab',exact:true}).click();assert.equal(await page.locator('#first-panel-input').inputValue(),'First');});
await check('duplicate and missing item values are disabled, then recover',async()=>{await page.locator('acme-accordion-item').nth(1).evaluate(el=>el.value='alpha');await page.waitForFunction(()=>[...document.querySelectorAll('#accordion acme-accordion-trigger')].every(el=>el.shadowRoot.querySelector('button').disabled));await page.locator('acme-accordion-item').nth(1).evaluate(el=>el.value='beta');await page.waitForFunction(()=>[...document.querySelectorAll('#accordion acme-accordion-trigger')].every(el=>!el.shadowRoot.querySelector('button').disabled));});
await check('dynamic hidden triggers are skipped by keyboard navigation',async()=>{await page.locator('acme-accordion-item').nth(1).evaluate(el=>el.style.display='none');await page.getByRole('button',{name:'Alpha',exact:true}).focus();await page.keyboard.press('ArrowDown');assert.equal(await page.getByRole('button',{name:'Alpha',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);});
await check('renderer content disconnects and remounts after exit',async()=>{await page.evaluate(()=>window.setupRenderContent());await page.getByRole('button',{name:'More details',exact:true}).click();await page.locator('#rendered-input').fill('Edited');await page.getByRole('button',{name:'More details',exact:true}).click();await page.waitForFunction(()=>!document.querySelector('#rendered-input'));await page.getByRole('button',{name:'More details',exact:true}).click();assert.equal(await page.locator('#rendered-input').inputValue(),'Rendered');});
await check('rapid motion reversal retains the open content',async()=>{await page.emulateMedia({reducedMotion:'no-preference'});await page.getByRole('button',{name:'More details',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#managed-input'));await page.locator('#single').evaluate(async el=>{el.expanded=false;await el.updateComplete;el.expanded=true});await page.waitForFunction(()=>{const content=document.querySelector('#single acme-collapsible-content');return !content.hidden&&!content.inert&&content.getBoundingClientRect().height>0});assert.equal(await page.locator('#managed-input').count(),1);await page.emulateMedia({reducedMotion:'reduce'});});
await check('nested sections retain independent owners and reconnect once',async()=>{await page.locator('#accordion').evaluate(el=>{const content=el.querySelector('acme-accordion-content');const nested=document.createElement('acme-collapsible');nested.id='nested';nested.innerHTML='<acme-collapsible-trigger>Nested section</acme-collapsible-trigger><acme-collapsible-content>Nested content</acme-collapsible-content>';content.append(nested);el.expanded=['alpha'];window.outerChanges=0;el.addEventListener('acme-expanded-change',e=>{if(e.target===el)window.outerChanges++})});await page.getByRole('button',{name:'Nested section',exact:true}).click();assert.deepEqual(await page.locator('#accordion').evaluate(el=>el.expanded),['alpha']);await page.locator('#accordion').evaluate(el=>{el.remove();document.body.prepend(el)});await page.getByRole('button',{name:'Beta',exact:true}).click();assert.equal(await page.evaluate(()=>window.outerChanges),1);assert.equal(await page.locator('#nested').evaluate(el=>el.expanded),true);});
await check('open content grows naturally after its content changes',async()=>{await page.getByRole('button',{name:'More details',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#managed-input'));const before=await page.locator('#single acme-collapsible-content').evaluate(el=>el.getBoundingClientRect().height);await page.locator('#single acme-collapsible-content input').evaluate(el=>{const block=document.createElement('div');block.style.height='150px';el.after(block)});await page.waitForFunction(before=>document.querySelector('#single acme-collapsible-content').getBoundingClientRect().height>before+140,before);});
await check('keyboard focus has a visible outline',async()=>{await page.getByRole('button',{name:'Alpha',exact:true}).focus();assert.equal(await page.getByRole('button',{name:'Alpha',exact:true}).evaluate(el=>getComputedStyle(el).outlineStyle),'solid');});

