await check('static messages stay passive and authored alert semantics reach one native root',async()=>{assert.equal(await page.getByRole('alert').count(),1);assert.equal(await page.locator('#static').evaluate(el=>el.shadowRoot.querySelector('[part=root]').getAttribute('role')),null);assert.equal(await page.getByRole('heading',{name:'Save failed',level:2}).count(),1);assert.equal(await page.locator('#live').evaluate(el=>Element.prototype.hasAttribute.call(el,'role')),false);});
await check('dismiss requests are cancelable and never remove application content by themselves',async()=>{await page.locator('#static').evaluate(el=>{window.requests=[];el.addEventListener('acme-request',e=>{window.requests.push({detail:e.detail,cancelable:e.cancelable});e.preventDefault()})});await page.getByRole('button',{name:'Dismiss message',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.requests),[{detail:{action:'dismiss'},cancelable:true}]);assert.equal(await page.locator('#static').isVisible(),true);assert.equal(await page.getByRole('button',{name:'View deployment',exact:true}).isEnabled(),true);});
await check('heading and action slots stay live and preserve native actions',async()=>{await page.locator('#static').evaluate(el=>{window.action=el.querySelector('acme-button');window.clicks=0;window.action.addEventListener('click',()=>window.clicks++);const heading=document.createElement('h3');heading.slot='heading';heading.textContent='New deployment';el.append(heading)});await page.getByRole('heading',{name:'New deployment',level:3}).waitFor();await page.getByRole('button',{name:'View deployment',exact:true}).click();assert.equal(await page.evaluate(()=>window.clicks),1);assert.equal(await page.evaluate(()=>window.action===document.querySelector('#static acme-button')),true);await page.locator('#static [slot=heading]').evaluate(el=>el.remove());await page.getByText('Deployment ready',{exact:true}).waitFor();});
await check('all treatments and sizes use real boxes and fit narrow RTL content',async()=>{await page.setViewportSize({width:360,height:700});await page.evaluate(()=>document.documentElement.dir='rtl');for(const variant of ['default','success','error','warning','secondary','violet','cyan'])for(const size of ['small','medium','large']){await page.locator('#static').evaluate((el,values)=>{el.variant=values.variant;el.size=values.size}, {variant,size});await page.locator('#static').evaluate(el=>el.updateComplete);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);assert.notEqual(await page.locator('#static').evaluate(el=>getComputedStyle(el).display),'contents');}await page.screenshot({path:dir+'/'+engine+'-messages.png'});});
await check('Banner keeps one message and action across viewport changes',async()=>{await page.locator('#banner').evaluate(el=>window.bannerChildren=[...el.childNodes]);await page.setViewportSize({width:360,height:700});await page.getByRole('link',{name:'View details'}).waitFor();await page.setViewportSize({width:1200,height:700});assert.equal(await page.getByRole('link',{name:'View details'}).count(),1);assert.equal(await page.locator('#banner').evaluate(el=>[...el.childNodes].every((node,index)=>node===window.bannerChildren[index])),true);});

