await page.mouse.move(900,700);
await page.emulateMedia({reducedMotion:'no-preference'});
await page.setViewportSize({width:1000,height:800});
await page.goto(server.url.href);
await page.locator('.book').waitFor();
await page.waitForTimeout(40);

body:
await check('default and CSS widths preserve the cover ratio',async()=>{let box=await page.locator('.wrap').boundingBox();assert.ok(Math.abs(box.width-196)<1);assert.ok(Math.abs(box.height/box.width-60/49)<.01);await page.locator('#book').evaluate(el=>el.width='300px');await page.waitForFunction(()=>Math.abs(document.querySelector('#book').shadowRoot.querySelector('.wrap').getBoundingClientRect().width-300)<1);box=await page.locator('.wrap').boundingBox();assert.ok(Math.abs(box.height/box.width-60/49)<.01);await page.locator('#book').evaluate(el=>el.width=40);await page.waitForFunction(()=>Math.abs(document.querySelector('#book').shadowRoot.querySelector('.wrap').getBoundingClientRect().width-160)<1)});
await check('responsive widths use window and named-container queries',async()=>{await page.locator('#book').evaluate(el=>el.width={compact:'150px',medium:'240px'});await page.waitForFunction(()=>document.querySelector('#book').measuredWidth===240);await page.setViewportSize({width:500,height:800});await page.waitForFunction(()=>document.querySelector('#book').measuredWidth===150);await page.locator('#book').evaluate(el=>{el.responsiveTarget='container';el.responsiveContainer='books'});await page.waitForFunction(()=>document.querySelector('#book').measuredWidth===240);await page.locator('#container').evaluate(el=>el.style.width='400px');await page.waitForFunction(()=>document.querySelector('#book').measuredWidth===150)});
await check('real hover starts from rest and reversal does not continue outward',async()=>{const bounds=await page.locator('.book').boundingBox();await page.mouse.move(bounds.x+bounds.width/2,bounds.y+bounds.height/2);await page.waitForTimeout(65);const before=await page.locator('.wrap').evaluate(el=>Math.abs(new DOMMatrix(getComputedStyle(el).transform).m13));assert.ok(before>0&&before<.38);await page.mouse.move(900,700);const samples=await page.locator('.wrap').evaluate(async el=>{const values=[];for(let i=0;i<8;i++){await new Promise(requestAnimationFrame);values.push(Math.abs(new DOMMatrix(getComputedStyle(el).transform).m13))}return values});assert.ok(samples.at(-1)<samples[0]);assert.ok(Math.max(...samples)<=before+.04);await page.waitForTimeout(260);assert.equal(await page.locator('.wrap').evaluate(el=>el.getAnimations().filter(a=>a.playState==='running').length),0)});
await check('reduced motion and a changed preference cancel active animations',async()=>{await page.emulateMedia({reducedMotion:'reduce'});const bounds=await page.locator('.book').boundingBox();await page.mouse.move(bounds.x+bounds.width/2,bounds.y+bounds.height/2);await page.waitForTimeout(30);assert.equal(await page.locator('.wrap').evaluate(el=>el.getAnimations().filter(a=>a.playState==='running').length),0);await page.mouse.move(900,700);await page.emulateMedia({reducedMotion:'no-preference'});await page.mouse.move(bounds.x+bounds.width/2,bounds.y+bounds.height/2);await page.waitForTimeout(30);await page.emulateMedia({reducedMotion:'reduce'});await page.waitForTimeout(30);assert.equal(await page.locator('.wrap').evaluate(el=>el.getAnimations().filter(a=>a.playState==='running').length),0)});
await check('touch stays at rest and authored marks remain owned across variants',async()=>{await page.locator('.book').dispatchEvent('pointerenter',{pointerType:'touch'});assert.equal(await page.evaluate(()=>window.book.gesture.get().hovered),false);await page.locator('#book').evaluate(el=>{const mark=document.createElement('span');mark.slot='start';mark.textContent='Custom';el.append(mark);window.mark=mark});await page.waitForFunction(()=>!document.querySelector('#book').shadowRoot.querySelector('acme-layers-icon'));await page.locator('#book').evaluate(el=>el.variant='simple');await page.locator('#book').evaluate(el=>el.variant='stripe');assert.equal(await page.evaluate(()=>window.mark===window.book.querySelector('[slot=start]')),true)});
await check('disconnect ends motion and reconnect starts from rest',async()=>{const bounds=await page.locator('.book').boundingBox();await page.mouse.move(bounds.x+bounds.width/2,bounds.y+bounds.height/2);await page.waitForTimeout(30);await page.evaluate(()=>window.book.remove());assert.equal(await page.evaluate(()=>window.book.shadowRoot.querySelector('.wrap').getAnimations().filter(a=>a.playState==='running').length),0);await page.mouse.move(900,700);await page.evaluate(()=>document.querySelector('#container').append(window.book));await page.locator('.book').waitFor();assert.equal(await page.evaluate(()=>window.book.gesture.get().hovered),false)});
await check('texture loads the packaged image only when requested',async()=>{const requests=[];page.on('request',request=>{if(request.url().includes('.avif'))requests.push(request.url())});assert.equal(await page.locator('.texture').count(),0);await page.locator('#book').evaluate(el=>el.textured=true);await page.locator('.texture').waitFor();const image=await page.locator('.texture').evaluate(async element=>{const url=JSON.parse(getComputedStyle(element).backgroundImage.slice(4,-1));const image=new Image();image.src=url;await image.decode();return {url,width:image.naturalWidth,height:image.naturalHeight}});assert.equal(new URL(image.url).origin,new URL(page.url()).origin);assert.ok(image.width>0&&image.height>0);assert.ok(requests.length>0);assert.equal(await page.locator('.texture').evaluate(el=>el.style.transform),'')});
await check('reenabling motion does not replay a consumed reduced-motion gesture',async()=>{await page.emulateMedia({reducedMotion:'reduce'});const box=await page.locator('.book').boundingBox();await page.mouse.move(box.x+box.width/2,box.y+box.height/2);await page.waitForTimeout(30);const before=await page.locator('.wrap').evaluate(el=>new DOMMatrix(getComputedStyle(el).transform).m13);await page.emulateMedia({reducedMotion:'no-preference'});await page.waitForTimeout(45);const after=await page.locator('.wrap').evaluate(el=>new DOMMatrix(getComputedStyle(el).transform).m13);assert.ok(Math.abs(after-before)<.01);assert.equal(await page.locator('.wrap').evaluate(el=>el.getAnimations().filter(animation=>animation.playState==='running').length),0)});
await check('page zoom preserves measured cover geometry',async()=>{await page.evaluate(()=>document.documentElement.style.zoom='2');await page.waitForTimeout(80);const geometry=await page.locator('#book').evaluate(el=>({host:el.getBoundingClientRect().toJSON(),root:el.shadowRoot.querySelector('.book').getBoundingClientRect().toJSON(),width:el.measuredWidth}));assert.ok(Math.abs(geometry.root.width-geometry.host.width)<1);assert.ok(Math.abs(geometry.root.height/geometry.root.width-60/49)<.01);assert.ok(Math.abs(geometry.width-196)<1)});

await check('HTML default and immediate native submission',async()=>{assert.equal(await page.locator('#calendar').evaluate(el=>el.value),'2026-09-10');assert.equal(await page.locator('#form').evaluate(el=>new FormData(el).get('date')),'2026-09-10');});
await check('native modal opens on the selected day and Escape restores focus',async()=>{await page.locator('#calendar [part=trigger]').click();await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('dialog').matches(':modal'));assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.activeElement?.getAttribute('data-date')),'2026-09-10');await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('#calendar').shadowRoot.querySelector('dialog').open);assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.activeElement===el.shadowRoot.querySelector('[part=trigger]')),true);});
await check('inline control label does not replace date button names',async()=>{assert.equal(await page.locator('#inline [data-date="2026-09-10"]').getAttribute('aria-label'),'Thursday, September 10, 2026');assert.equal(await page.locator('#inline div[part=root]').getAttribute('role'),'group');});
await check('day selection commits one ISO value',async()=>{await page.locator('#calendar').evaluate(el=>{window.changes=[];el.addEventListener('acme-change',event=>window.changes.push(event.detail.value));el.show()});await page.locator('#calendar [data-date="2026-09-11"]').click();assert.deepEqual(await page.evaluate(()=>window.changes),['2026-09-11']);assert.equal(await page.locator('#form').evaluate(el=>new FormData(el).get('date')),'2026-09-11');});
await check('native label focuses the actual Calendar trigger',async()=>{await page.locator('#after').focus();await page.locator('label[for=calendar]').click();assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.activeElement===el.shadowRoot.querySelector('[part=trigger]')),true);});
await check('Apply explains an incomplete required range',async()=>{await page.locator('#calendar').evaluate(el=>{el.mode='range';el.required=true;el.show()});await page.locator('#calendar').getByRole('button',{name:'Apply',exact:true}).click();assert.equal(await page.locator('#calendar [role=alert]').count(),1);assert.equal(await page.locator('#calendar').evaluate(el=>el.open),true);});
await check('selecting the current day does not emit a change',async()=>{await page.locator('#inline').evaluate(el=>{window.sameChanges=0;el.addEventListener('acme-change',()=>window.sameChanges++);});await page.locator('#inline [data-date="2026-09-10"]').click();assert.equal(await page.evaluate(()=>window.sameChanges),0);});
await check('range endpoint navigation starts at the focused end',async()=>{await page.locator('#inline').evaluate(el=>el.mode='range');await page.locator('#inline [data-date="2026-09-12"]').click();await page.keyboard.press('ArrowRight');assert.equal(await page.locator('#inline').evaluate(el=>el.shadowRoot.activeElement?.getAttribute('data-date')),'2026-09-13');});
await check('date-only selection stays a civil day across zones',async()=>{await page.locator('#calendar').evaluate(el=>{el.value='2011-12-30';el.timeZone='Pacific/Apia'});await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('[part=trigger]').textContent.includes('Dec 30, 2011'));assert.equal(await page.locator('#calendar').evaluate(el=>el.value),'2011-12-30');});
await check('time-zone changes preserve the timestamp instant',async()=>{await page.locator('#calendar').evaluate(el=>{el.timeZone='America/Los_Angeles';el.showTimeInput=true;el.value='2026-09-22T01:30:00-07:00';el.timeZone='UTC'});await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('[data-time=start]').value.startsWith('08:30'));assert.equal(await page.locator('#calendar').evaluate(el=>el.value),'2026-09-22T01:30:00-07:00');});
await check('DST gap remains invalid until time is corrected',async()=>{await page.locator('#calendar').evaluate(el=>{el.timeZone='America/Los_Angeles';el.showTimeInput=true;el.value='2026-03-08T01:30:00-08:00';el.show()});await page.locator('#calendar [data-time=start]').fill('02:30');assert.equal(await page.locator('#calendar').evaluate(el=>el.checkValidity()),false);assert.equal(await page.locator('#calendar').evaluate(el=>el.value),'2026-03-08T01:30:00-08:00');await page.locator('#calendar [data-time=start]').fill('03:30');assert.equal(await page.locator('#calendar').evaluate(el=>el.checkValidity()),true);assert.equal(await page.locator('#calendar').evaluate(el=>el.value),'2026-03-08T03:30:00-07:00');});
await check('bounds restrict native validity and date buttons',async()=>{await page.locator('#inline').evaluate(el=>{el.minValue='2026-09-05';el.maxValue='2026-09-20';el.value='2026-09-01'});assert.equal(await page.locator('#inline').evaluate(el=>el.validity.rangeUnderflow),true);await page.waitForFunction(()=>document.querySelector('#inline').shadowRoot.querySelector('[data-date="2026-09-01"]').disabled);await page.locator('#inline').evaluate(el=>el.value='2026-09-12');assert.equal(await page.locator('#inline').evaluate(el=>el.checkValidity()),true);});
await check('native reset and restoration stay silent',async()=>{assert.deepEqual(await page.locator('#calendar').evaluate(el=>{let changed=0;el.addEventListener('acme-change',()=>changed++);el.value='2026-09-12';HTMLFormElement.prototype.reset.call(el.form);const reset=el.value;el.formStateRestoreCallback('{"value":"2026-09-15"}','restore');return[reset,el.value,changed,new FormData(el.form).get('date')]}),['2026-09-10','2026-09-15',0,'2026-09-15']);});
await check('native fieldset disables submission immediately',async()=>{assert.deepEqual(await page.locator('#calendar').evaluate(el=>{const group=document.createElement('fieldset');el.before(group);group.append(el);group.disabled=true;const absent=!new FormData(el.form).has('date');group.disabled=false;return[absent,new FormData(el.form).get('date')]}),[true,'2026-09-10']);});
await check('footer identity survives presentation changes',async()=>{await page.locator('#inline').evaluate(async el=>{const input=document.createElement('input');input.slot='footer';input.id='footer';input.value='Retained';el.append(input);window.footer=input;el.presentation='popover';await el.updateComplete;el.presentation='inline';await el.updateComplete;});assert.equal(await page.locator('#footer').evaluate(el=>el===window.footer&&el.value==='Retained'),true);});
await check('range value serializes as one JSON entry',async()=>{assert.deepEqual(await page.locator('#calendar').evaluate(el=>{el.mode='range';el.value={start:'2026-09-10',end:'2026-09-12'};return new FormData(el.form).getAll('date')}),['{"start":"2026-09-10","end":"2026-09-12"}']);});
await check('open modal can change presentation and reopen',async()=>{await page.locator('#calendar').evaluate(el=>el.show());await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('dialog')?.matches(':modal'));await page.locator('#calendar').evaluate(el=>el.presentation='inline');await page.waitForFunction(()=>!document.querySelector('#calendar').shadowRoot.querySelector('dialog'));assert.equal(await page.locator('#calendar').evaluate(el=>el.open),false);await page.locator('#calendar').evaluate(el=>{el.presentation='popover'});await page.locator('#calendar').evaluate(async el=>{await el.updateComplete;el.show()});await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('dialog')?.matches(':modal'));});
await check('controlled rejection does not emit a commit',async()=>{await page.locator('#inline').evaluate(el=>{window.rejectedChanges=0;el.addEventListener('acme-input',()=>el.value='2026-09-10');el.addEventListener('acme-change',()=>window.rejectedChanges++);});await page.locator('#inline [data-date="2026-09-11"]').click();assert.equal(await page.locator('#inline').evaluate(el=>el.value),'2026-09-10');assert.equal(await page.evaluate(()=>window.rejectedChanges),0);});
await check('trigger exposes current dialog relationship and expansion',async()=>{assert.equal(await page.locator('#calendar [part=trigger]').getAttribute('aria-haspopup'),'dialog');assert.equal(await page.locator('#calendar [part=trigger]').getAttribute('aria-expanded'),'false');await page.locator('#calendar [part=trigger]').click();assert.equal(await page.locator('#calendar [part=trigger]').getAttribute('aria-expanded'),'true');assert.equal(await page.locator('#calendar [part=trigger]').evaluate(el=>el.ariaControlsElements?.[0]===el.getRootNode().querySelector('dialog')),true);});
await check('external label updates retain owned popup semantics',async()=>{await page.locator('#calendar').evaluate(el=>el.show());await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('dialog').matches(':modal'));await page.evaluate(()=>{const label=document.querySelector('label[for=calendar]');label.textContent='Updated deadline';});await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await page.locator('#calendar [part=trigger]').getAttribute('aria-haspopup'),'dialog');assert.equal(await page.locator('#calendar [part=trigger]').getAttribute('aria-expanded'),'true');});
await check('month buttons retain focus for repeated activation',async()=>{await page.locator('#calendar').evaluate(el=>el.show());const next=page.locator('#calendar').getByRole('button',{name:'Next month',exact:true});await next.focus();await page.keyboard.press('Enter');assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.activeElement?.getAttribute('aria-label')),'Next month');await page.keyboard.press('Enter');assert.ok((await page.locator('#calendar h2').textContent()).includes('November'));});
await check('short viewport reveals the selected focused day',async()=>{await page.setViewportSize({width:400,height:300});await page.locator('#calendar').evaluate(el=>{el.value='2026-09-28';el.show()});await page.waitForFunction(()=>{const r=document.querySelector('#calendar'),d=r.shadowRoot.querySelector('dialog'),b=r.shadowRoot.querySelector('[data-date="2026-09-28"]');return b.getBoundingClientRect().bottom<=d.getBoundingClientRect().bottom+1});const sizes=await page.locator('#calendar').evaluate(el=>{const d=el.shadowRoot.querySelector('dialog').getBoundingClientRect();return{x:d.x,right:d.right,bottom:d.bottom}});assert.ok(sizes.x>=0&&sizes.right<=400&&sizes.bottom<=300);await page.setViewportSize({width:1280,height:720});});
await check('presets use immutable values and native JSON submission',async()=>{await page.locator('#calendar').evaluate(el=>{const data=[{label:'Release',value:{start:'2026-09-11',end:'2026-09-15'}}];el.mode='range';el.presets=data;data[0].value.end='2026-09-20';el.show()});await page.locator('#calendar').getByRole('button',{name:'Release',exact:true}).click();assert.equal(await page.locator('#form').evaluate(el=>new FormData(el).get('date')),'{"start":"2026-09-11","end":"2026-09-15"}');});
await check('changing zone clears a stale local-time draft error',async()=>{await page.locator('#calendar').evaluate(el=>{el.timeZone='America/Los_Angeles';el.showTimeInput=true;el.value='2026-03-08T01:30:00-08:00';el.show()});await page.locator('#calendar [data-time=start]').fill('02:30');assert.equal(await page.locator('#calendar').evaluate(el=>el.checkValidity()),false);assert.equal(await page.locator('#calendar').evaluate(el=>{el.timeZone='UTC';return el.checkValidity()}),true);});
await check('RTL day keys follow the visual direction',async()=>{await page.locator('#inline').evaluate(el=>el.dir='rtl');await page.locator('#inline [data-date="2026-09-10"]').press('ArrowLeft');assert.equal(await page.locator('#inline').evaluate(el=>el.shadowRoot.activeElement?.getAttribute('data-date')),'2026-09-11');});
await check('modal Tab stays contained and reaches supplied footer',async()=>{await page.locator('#calendar').evaluate(el=>{const input=document.createElement('input');input.slot='footer';input.id='calendar-footer';input.setAttribute('aria-label','Footer');el.append(input);el.show()});let reached=false;for(let index=0;index<18;index++){await page.keyboard.press('Tab');const result=await page.locator('#calendar').evaluate(el=>{let active=el.ownerDocument.activeElement;while(active?.shadowRoot?.activeElement)active=active.shadowRoot.activeElement;const footer=active?.id==='calendar-footer';const dialog=el.shadowRoot.querySelector('dialog');let node=active;while(node){if(node===dialog)return{inside:true,footer};node=node.assignedSlot??node.parentNode??node.host;}return{inside:false,footer};});assert.equal(result.inside,true);reached ||= result.footer;}assert.equal(reached,true);});
await check('nested modal releases focus back to its open parent',async()=>{await page.locator('#calendar').evaluate(async el=>{const child=document.createElement('acme-calendar');child.id='child-calendar';child.slot='footer';child.mode='single';child.showTimeInput=false;child.value='2026-09-10';el.append(child);el.show();await el.updateComplete;await child.updateComplete;child.show()});await page.waitForFunction(()=>document.querySelector('#child-calendar').shadowRoot.querySelector('dialog').matches(':modal'));await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('#child-calendar').shadowRoot.querySelector('dialog').open);assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.querySelector('dialog').matches(':modal')),true);assert.equal(await page.locator('#child-calendar').evaluate(el=>el.shadowRoot.activeElement===el.shadowRoot.querySelector('[part=trigger]')),true);await page.keyboard.press('Tab');assert.equal(await page.locator('#calendar').evaluate(el=>{let a=el.ownerDocument.activeElement;while(a?.shadowRoot?.activeElement)a=a.shadowRoot.activeElement;for(let n=a;n;n=n.assignedSlot??n.parentNode??n.host)if(n===el.shadowRoot.querySelector('dialog'))return true;return false}),true);await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('#calendar').shadowRoot.querySelector('dialog').open);});
await check('removing an open modal releases focus resources before reconnect',async()=>{await page.locator('#calendar').evaluate(el=>el.show());await page.locator('#calendar').evaluate(el=>{window.removedCalendar=el;el.remove()});await page.locator('#after').focus();await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement?.localName==='body'||!document.activeElement?.closest('#calendar')),true);await page.evaluate(()=>document.querySelector('#form').prepend(window.removedCalendar));await page.locator('#calendar').evaluate(el=>el.show());await page.waitForFunction(()=>document.querySelector('#calendar').shadowRoot.querySelector('dialog').matches(':modal'));await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('#calendar').shadowRoot.querySelector('dialog').open);assert.equal(await page.locator('#calendar').evaluate(el=>el.shadowRoot.activeElement===el.shadowRoot.querySelector('[part=trigger]')),true);});

