body:
await check('the chart exposes a meaningful native name and exact values',async()=>{await page.getByRole('img',{name:'Weekly requests',exact:true}).waitFor();await page.getByRole('button',{name:'View data',exact:true}).click();await page.locator('acme-chart acme-table table').waitFor();assert.equal(await page.locator('tbody tr').first().locator('td').first().textContent(),'0');assert.equal(await page.locator('tbody tr').last().locator('td').last().textContent(),'—');});
await check('all three mark types rebuild without leaking extra SVG surfaces',async()=>{for(const type of ['bar','area','line']){await page.locator('#chart').evaluate((el,type)=>el.type=type,type);await page.waitForTimeout(80);assert.equal(await page.locator('#chart svg.ts-chart').count(),1);assert.ok(await page.locator('#chart svg.ts-chart').evaluate(svg=>svg.querySelectorAll('path,rect,polyline').length>0));}});
await check('keyboard inspection is available while activation remains explicitly opt-in',async()=>{await page.getByRole('img',{name:'Weekly requests',exact:true}).focus();await page.keyboard.press('ArrowRight');await page.keyboard.press('Enter');assert.equal(await page.evaluate(()=>window.requests.length),0);await page.evaluate(()=>window.chart.interactive=true);await page.keyboard.press('Enter');assert.equal(await page.evaluate(()=>window.requests.length),1);assert.equal(await page.evaluate(()=>window.requests[0].action),'point');assert.equal(typeof await page.evaluate(()=>window.requests[0].index),'number');});
await check('clearing data removes the renderer and reconnect creates one current surface',async()=>{await page.evaluate(()=>{window.saved=window.chart.data;window.chart.data=[]});await page.waitForFunction(()=>document.querySelector('#chart').shadowRoot.querySelector('svg')===null);await page.getByText('No data',{exact:true}).waitFor();await page.evaluate(()=>{window.chart.remove();window.chart.data=window.saved;document.body.append(window.chart)});await page.getByRole('img',{name:'Weekly requests',exact:true}).waitFor();assert.equal(await page.locator('#chart svg.ts-chart').count(),1);});
await check('height, width and typed numerical/date axes use current measurements',async()=>{await page.locator('#chart').evaluate(el=>{el.height='260px';el.style.width='420px';el.data=[{x:new Date('2026-01-01'),requests:2},{x:new Date('2026-02-01'),requests:4}];el.series=[{key:'requests',label:'Requests'}]});await page.waitForFunction(()=>document.querySelector('#chart').shadowRoot.querySelector('svg')?.viewBox.baseVal.height===260);const rect=await page.locator('#chart svg.ts-chart').boundingBox();assert.ok(rect.width<=421);assert.ok(await page.locator('#chart svg.ts-chart text').count()>0);});
await check('Sparkline keeps gaps, separate sentiment and decorative semantics',async()=>{await page.evaluate(()=>{const spark=document.createElement('acme-sparkline');spark.id='spark';spark.values=[1,2,null,4,3];spark.direction='down';spark.sentiment='positive';document.body.append(spark)});await page.locator('#spark svg').waitFor();assert.equal(await page.locator('#spark svg').getAttribute('aria-hidden'),'true');assert.ok(await page.locator('#spark [part=line]').count()>0);assert.ok(await page.locator('#spark [part=fill]').count()>0);await page.locator('#spark').evaluate(el=>el.label='Fewer delivery failures');await page.getByRole('img',{name:'Fewer delivery failures',exact:true}).waitFor();assert.ok((await page.locator('#spark svg').textContent()).includes('Down, Favorable'));await page.locator('#spark').evaluate(el=>el.values=[]);await page.waitForFunction(()=>document.querySelector('#spark').shadowRoot.querySelector('svg')===null);});
await check('Legend labels and authored controls remain passive and native hidden stays hidden',async()=>{await page.evaluate(()=>{const legend=document.createElement('acme-legend');legend.id='legend';legend.orientation='vertical';legend.innerHTML='<acme-legend-item value="a" label="Requests" color="blue"></acme-legend-item><acme-legend-item value="b"><button id="legend-action">Toggle errors</button></acme-legend-item>';document.body.append(legend);window.legendClicks=0;document.querySelector('#legend-action').addEventListener('click',()=>window.legendClicks++)});await page.getByText('Requests',{exact:true}).last().waitFor();await page.getByRole('button',{name:'Toggle errors'}).click();assert.equal(await page.evaluate(()=>window.legendClicks),1);await page.locator('#legend acme-legend-item').first().evaluate(el=>el.hidden=true);assert.equal(await page.locator('#legend acme-legend-item').first().isVisible(),false);});
await check('supplementary tooltip content retains author nodes and formatters remain text',async()=>{await page.locator('#chart').evaluate(el=>{el.innerHTML='<span slot="tooltip" id="supplement">Recorded requests</span>';window.supplement=el.querySelector('#supplement');el.series=[{key:'requests',label:'Requests',formatter:value=>'<b>'+value+'</b>'}];el.focus()});await page.keyboard.press('ArrowRight');await page.locator('#chart [part=tooltip]').waitFor();assert.equal(await page.locator('#chart [part=tooltip] b b').count(),0);assert.equal(await page.evaluate(()=>window.supplement===window.chart.querySelector('#supplement')),true);assert.ok((await page.locator('#chart [part=tooltip]').textContent()).includes('<b>'));});
await check('a missing required label does not mount an unnamed interactive graphic',async()=>{await page.locator('#chart').evaluate(el=>el.label='');await page.waitForFunction(()=>document.querySelector('#chart').shadowRoot.querySelector('svg')===null);});

await check('exact source includes leading/trailing whitespace and copy emits once',async()=>{await page.getByRole('button',{name:'Copy',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.writes),['\nconst first = 1;  \nconst second = 2;\n']);assert.equal(await page.locator('[part=line]').count(),4);assert.ok(await page.locator('.token.keyword').count()>0)});
await check('one keyboard entry moves between references and requests without owning state or history',async()=>{assert.equal(await page.locator('[part=line-number][tabindex="0"]').count(),1);await page.getByRole('button',{name:'Reference line 1',exact:true}).focus();await page.keyboard.press('ArrowDown');await page.keyboard.press('Enter');assert.deepEqual(await page.evaluate(()=>window.requests),[{action:'reference-line',line:2}]);assert.equal(await page.evaluate(()=>window.code.referencedLine),undefined);assert.equal(new URL(page.url()).hash,'');await page.keyboard.press('End');assert.equal(await page.getByRole('button',{name:'Reference line 4',exact:true}).evaluate(el=>el===el.getRootNode().activeElement),true)});
await check('overlapping decorations remain explicit and out-of-range values add no lines',async()=>{await page.evaluate(()=>{window.code.highlightedLines=[2,99];window.code.addedLines=[2];window.code.removedLines=[2];window.code.referencedLine=2});await page.waitForFunction(()=>document.querySelector('#code').shadowRoot.querySelector('[data-line="2"]').hasAttribute('data-active'));for(const attribute of ['data-highlighted','data-added','data-removed','data-active'])assert.equal(await page.locator('[part=line]').nth(1).getAttribute(attribute),'true');assert.equal(await page.locator('[part=line]').count(),4)});
await check('long code scrolls internally and wrapping preserves source',async()=>{await page.evaluate(()=>{window.code.style.width='320px';window.code.style.setProperty('--acme-code-block-max-height','140px');window.code.code=Array.from({length:100},(_,i)=>'const item'+i+' = "'+ 'wide '.repeat(20)+'";').join('\n')});await page.waitForFunction(()=>document.querySelector('#code').shadowRoot.querySelectorAll('[part=line]').length===100);await page.evaluate(()=>window.code.scrollToLine(90));await page.waitForFunction(()=>document.querySelector('#code').shadowRoot.querySelector('acme-scroll-viewport').getViewport().scrollTop>1000);await page.evaluate(()=>{window.code.code='const message = "'+'long '.repeat(100)+'";';window.code.wrap=true});await page.waitForFunction(()=>document.querySelector('#code').shadowRoot.querySelector('[data-wrap]'));const geometry=await page.locator('acme-scroll-viewport').evaluate(el=>{const v=el.getViewport();return {width:v.clientWidth,scroll:v.scrollWidth}});assert.ok(geometry.scroll<=geometry.width+1)});
await check('failure renders safe plain text and reports once per prepared source',async()=>{await page.evaluate(()=>{window.highlighter.tokenize=()=>{throw Error('test failure')};window.code.code='<img src=x onerror=bad()>\n';window.code.language='html'});await page.waitForFunction(()=>window.errors.length===1);assert.equal(await page.locator('#code img').count(),0);assert.ok((await page.locator('[part=code]').textContent()).includes('<img'));await page.evaluate(()=>window.code.filename='renamed.html');await page.waitForTimeout(50);assert.equal(await page.evaluate(()=>window.errors.length),1)});
await check('empty source, authored controls and changed source preserve their owners',async()=>{await page.evaluate(()=>{window.code.innerHTML='<input slot="end" id="file-control" value="Owned"><span slot="empty">Empty file</span>';window.saved=window.code.querySelector('#file-control')});await page.locator('#file-control').focus();await page.evaluate(()=>window.code.code='');await page.getByText('Empty file',{exact:true}).waitFor();assert.equal(await page.locator('[part=line]').count(),0);assert.equal(await page.evaluate(()=>window.saved===window.code.querySelector('#file-control')),true);assert.equal(await page.locator('#file-control').evaluate(el=>el===document.activeElement),true)});
await check('replacing short source recovers focused line navigation',async()=>{await page.getByRole('button',{name:'Reference line 4',exact:true}).focus();await page.evaluate(()=>window.code.code='replacement');await page.waitForFunction(()=>document.querySelector('#code').shadowRoot.querySelectorAll('[part=line]').length===1);assert.equal(await page.getByRole('button',{name:'Reference line 1',exact:true}).evaluate(el=>el===el.getRootNode().activeElement),true)});

