body:
const input=()=>page.getByRole('combobox',{name:'Search commands',exact:true});
await check('Command Menu composes one native Dialog and an active-descendant Input',async()=>{assert.equal(await page.locator('#commands dialog').count(),1);assert.equal(await page.locator('#commands dialog').evaluate(el=>el.matches(':modal')),true);assert.equal(await input().evaluate(el=>el.ariaControlsElements?.[0]?.getAttribute('role')),'listbox');assert.equal(await input().evaluate(el=>el.ariaActiveDescendantElement?.value),'create');assert.equal(await input().getAttribute('aria-autocomplete'),'list');});
await check('typing searches visible labels and aliases without moving author nodes',async()=>{await page.locator('#projects').evaluate(el=>window.original=[...el.children]);await input().fill('workspace');assert.equal(await page.locator('#commands').evaluate(el=>el.query),'workspace');await page.waitForFunction(()=>document.querySelector('#commands').shadowRoot.querySelector('acme-input').ariaActiveDescendantElement?.value==='open');assert.equal(await page.locator('#open-project').isVisible(),true);assert.equal(await page.locator('acme-command-item[value=create]').isVisible(),false);assert.equal(await page.locator('#projects').evaluate(el=>[...el.children].every((node,i)=>node===window.original[i])),true);});
await check('arrow activation reports one serializable request and closes',async()=>{await page.locator('#commands').evaluate(el=>{window.requests=[];window.openChanges=[];el.addEventListener('acme-request',e=>window.requests.push(e.detail));el.addEventListener('acme-open-change',e=>window.openChanges.push(e.detail))});await input().press('ArrowDown');await input().press('Enter');await page.waitForFunction(()=>!document.querySelector('#commands').open);assert.deepEqual(await page.evaluate(()=>window.requests),[{action:'select',value:'open'}]);assert.deepEqual(await page.evaluate(()=>window.openChanges),[{open:false,reason:'selection'}]);});
await check('canceling a selection keeps the menu and its query',async()=>{await page.locator('#commands').evaluate(el=>el.addEventListener('acme-request',e=>{if(e.detail.action==='select')e.preventDefault()}));await input().fill('settings');await input().press('Enter');assert.equal(await page.locator('#commands').evaluate(el=>el.open),true);assert.equal(await input().inputValue(),'settings');});
await check('disabled items cannot activate',async()=>{await page.locator('#commands').evaluate(el=>{window.requests=0;el.addEventListener('acme-request',()=>window.requests++)});await page.locator('acme-command-item[value=disabled]').click();assert.equal(await page.evaluate(()=>window.requests),0);assert.equal(await page.locator('#commands').evaluate(el=>el.open),true);});
await check('Escape cancellation and completion follow the shared Dialog path',async()=>{await page.locator('#commands').evaluate(el=>{window.requests=0;el.addEventListener('acme-request',e=>{if(e.detail.action==='close'){window.requests++;if(window.requests===1)e.preventDefault()}})});await input().press('Escape');assert.equal(await page.locator('#commands').evaluate(el=>el.open),true);await input().press('Escape');await page.waitForFunction(()=>!document.querySelector('#commands').open);assert.equal(await page.evaluate(()=>window.requests),2);});
await check('empty results and programmatic query updates stay usable',async()=>{await page.locator('#commands').evaluate(el=>{window.inputs=0;el.addEventListener('acme-input',()=>window.inputs++);el.query='no-match-xyz'});await page.getByText('No matching actions',{exact:true}).waitFor();assert.equal(await input().evaluate(el=>el.ariaActiveDescendantElement),null);assert.equal(await page.evaluate(()=>window.inputs),0);await input().fill('project');assert.equal(await page.evaluate(()=>window.inputs),1);});
