await check('form fields retain accessible names and narrow RTL layout',async()=>{await page.setViewportSize({width:360,height:640});await page.evaluate(()=>{document.documentElement.dir='rtl';window.feedback.collectEmail=true;window.feedback.topics=[{value:'docs',label:'Documentation'}]});assert.equal(await page.locator('acme-textarea textarea').getAttribute('aria-label'),null);if(engine==='chromium'){const client=await page.context().newCDPSession(page),ax=await client.send('Accessibility.getFullAXTree');assert.ok(ax.nodes.some(n=>!n.ignored&&n.role?.value==='textbox'&&n.name?.value==='Message'));assert.ok(ax.nodes.some(n=>!n.ignored&&n.role?.value==='radiogroup'&&n.name?.value==='How was your experience?'));await client.detach();}assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:dir+'/'+engine+'-feedback.png'});});
