await check('Toggle Tip composition retains the draft and owns dismissal',async()=>{await page.locator('#feedback').evaluate(el=>{const help=document.createElement('acme-toggle-tip');help.innerHTML='<span slot="trigger">Feedback help</span>';el.before(help);help.append(el)});await page.getByRole('button',{name:'Feedback help',exact:true}).focus();await page.keyboard.press('Enter');await page.locator('acme-textarea textarea').fill('Keep draft');await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('acme-toggle-tip').open);await page.keyboard.press('Enter');await page.locator('acme-textarea textarea').waitFor();assert.equal(await page.locator('acme-textarea textarea').inputValue(),'Keep draft');});
await check('rating keyboard navigation updates one form value and both edit events',async()=>{await page.locator('acme-radio-card input').first().focus();await page.keyboard.press('ArrowRight');assert.equal(await page.evaluate(()=>window.feedback.value.rating),'dissatisfied');assert.equal(await page.evaluate(()=>window.inputs.at(-1).value.rating),'dissatisfied');assert.equal(await page.evaluate(()=>window.changes.at(-1).value.rating),'dissatisfied');});
await check('Dialog composition exposes one form and retains draft across dismissal',async()=>{await page.locator('#feedback').evaluate(el=>{const dialog=document.createElement('acme-dialog');dialog.ariaLabel='Feedback dialog';el.before(dialog);dialog.append(el);dialog.open=true});await page.locator('dialog').waitFor();await page.locator('acme-textarea textarea').fill('Dialog draft');await page.keyboard.press('Escape');await page.waitForFunction(()=>!document.querySelector('acme-dialog').open);await page.evaluate(()=>document.querySelector('acme-dialog').open=true);await page.locator('acme-textarea textarea').waitFor();assert.equal(await page.locator('acme-textarea textarea').inputValue(),'Dialog draft');});
await check('a tall Toggle Tip form remains reachable when neither side of its trigger fits',async()=>{await page.setViewportSize({width:700,height:500});await page.locator('#feedback').evaluate(el=>{const help=document.createElement('acme-toggle-tip');help.style.position='fixed';help.style.top='230px';help.style.left='80px';help.innerHTML='<span slot="trigger">Middle feedback</span>';el.before(help);help.append(el);el.collectEmail=true});await page.getByRole('button',{name:'Middle feedback'}).click();await page.locator('acme-textarea textarea').fill('Visible action');await page.getByRole('button',{name:'Send feedback'}).click();await page.waitForFunction(()=>window.requests.length===1);const box=await page.locator('acme-toggle-tip').evaluate(el=>el.shadowRoot.querySelector('[part=content]').getBoundingClientRect().toJSON());assert.ok(box.y>=0&&box.y+box.height<=501);});

await check('real worker renders measured custom nodes and routed edges',async()=>{assert.equal(page.workers().length,1);assert.equal(await page.locator('[data-arrow]').count(),6);assert.equal(await page.locator('[data-flow-fallback]').count(),5);await page.screenshot({path:dir+'/'+engine+'-flow.png'});assert.equal(await page.locator('acme-flow-node').isVisible(),true)});
await check('custom controls retain DOM, focus and values after layout',async()=>{await page.locator('#draft').fill('Preserved');await page.locator('#draft').focus();await page.evaluate(async()=>{window.saved=document.querySelector('#draft');window.flow.direction='down';await window.flow.layout()});assert.equal(await page.evaluate(()=>window.saved===document.querySelector('#draft')),true);assert.equal(await page.locator('#draft').inputValue(),'Preserved');assert.equal(await page.locator('#draft').evaluate(el=>el===document.activeElement),true);await page.evaluate(()=>window.flow.fit());await page.getByRole('button',{name:'Inside action',exact:true}).click();assert.equal(await page.evaluate(()=>window.inside),1);assert.equal(await page.evaluate(()=>window.requests.length),0)});
await check('node activation and keyboard viewport controls have distinct events',async()=>{await page.getByRole('button',{name:'Step 0',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.requests[0]),{action:'node',id:'n0'});const before=await page.evaluate(()=>window.flow.zoom);await page.getByRole('button',{name:'Zoom in',exact:true}).click();assert.ok(await page.evaluate(()=>window.flow.zoom)>before);assert.equal(await page.evaluate(()=>window.changes.length),1);await page.locator('[part=background]').focus();await page.keyboard.press('ArrowRight');assert.equal(await page.evaluate(()=>window.changes.length),2);await page.getByRole('button',{name:'View relationships',exact:true}).click();assert.ok((await page.locator('acme-collapsible-content').textContent()).includes('Refine and return'))});
await check('content resize relayout keeps author content mounted',async()=>{const before=await page.locator('acme-flow-node').boundingBox();await page.evaluate(()=>{const extra=document.createElement('div');extra.textContent='More information';extra.style.height='150px';document.querySelector('acme-flow-node').append(extra)});await page.waitForFunction(()=>window.flow.scene?.nodes.get('n1').height>200);const after=await page.locator('acme-flow-node').boundingBox();assert.ok(after.height>before.height);assert.equal(page.workers().length,1)});
await check('invalid references fail clearly and valid data recovers',async()=>{await page.evaluate(()=>window.flow.edges=[{id:'bad',source:'missing',target:'n0'}]);await page.waitForFunction(()=>window.failures.length>0);await page.evaluate(async()=>{window.flow.edges=[];await window.flow.layout()});assert.equal(await page.locator('[part=edge]').count(),0);assert.equal(await page.getByRole('button',{name:'Step 0',exact:true}).isVisible(),true)});
await check('empty, disconnect and reconnect release worker resources',async()=>{await page.evaluate(()=>window.flow.remove());await page.waitForTimeout(30);assert.equal(page.workers().length,0);await page.evaluate(()=>document.body.append(window.flow));await page.waitForFunction(()=>!!window.flow.engine.engine);await page.evaluate(async()=>{document.querySelector('acme-flow-node').remove();window.flow.nodes=[];window.flow.edges=[];await window.flow.layout()});await page.getByText('No nodes',{exact:true}).waitFor();assert.equal(await page.locator('[part=edge]').count(),0)});
await check('background pointer pan never captures nested control gestures',async()=>{const box=await page.locator('[part=background]').boundingBox();await page.mouse.move(box.x+30,box.y+30);await page.mouse.down();await page.mouse.move(box.x+100,box.y+60);await page.mouse.up();assert.ok(await page.evaluate(()=>window.changes.length)>0);const count=await page.evaluate(()=>window.changes.length);await page.locator('#draft').click();await page.keyboard.press('ArrowLeft');assert.equal(await page.evaluate(()=>window.changes.length),count)});
await check('invalid data emits once and a changed zoom range clamps current state',async()=>{await page.evaluate(()=>window.flow.edges=[{id:'bad',source:'missing',target:'n0'}]);await page.waitForFunction(()=>window.failures.length>0);await page.waitForTimeout(150);assert.equal(await page.evaluate(()=>window.failures.length),1);await page.evaluate(async()=>{window.flow.edges=[];window.flow.minZoom=1.2;await window.flow.layout()});assert.equal(await page.evaluate(()=>window.flow.zoom),1.2)});
await check('stale requests reject and latest data wins',async()=>{const result=await page.evaluate(async()=>{const flow=window.flow;const first=flow.layout().then(()=> 'resolved',e=>e.name);await new Promise(resolve=>setTimeout(resolve,0));flow.edges=[];await flow.layout();return {first:await first,edges:flow.scene.edges.length,busy:flow.busy}});assert.equal(result.first,'AbortError');assert.equal(result.edges,0);assert.equal(result.busy,false)});
await check('failed worker delivery has a usable retry and releases resources',async()=>{await page.evaluate(()=>window.configureFlowDiagram({workerUrl:'/missing-worker.js'}));await page.waitForFunction(()=>window.failures.length>0);await page.waitForTimeout(30);assert.equal(page.workers().length,0);await page.getByRole('button',{name:'Retry',exact:true}).waitFor();await page.evaluate(()=>window.configureFlowDiagram({workerUrl:'/elk-worker.js'}));await page.waitForFunction(()=>window.flow.scene?.edges.length===6);assert.equal(page.workers().length,1)});
await check('100 and 500 node worker layouts keep the main thread responsive and routes clear',async()=>{const measurements=[];for(const count of [100,500]){const result=await page.evaluate(async count=>{const flow=window.flow;document.querySelector('acme-flow-node')?.remove();flow.nodes=Array.from({length:count},(_,i)=>({id:'n'+i,label:'Node '+i,width:140+i%3*20,height:60+i%2*20}));flow.edges=flow.nodes.slice(1).map((node,i)=>({id:'e'+i,source:'n'+i,target:node.id,label:i%10===0?'Next stage':undefined}));flow.edges=[...flow.edges,...Array.from({length:Math.floor(count/10)},(_,i)=>({id:'back'+i,source:'n'+(i*10+5),target:'n'+(i*10+1),label:'Return'}))];let ticks=0;const timer=setInterval(()=>ticks++,10),start=performance.now();await flow.layout();clearInterval(timer);const layoutMs=performance.now()-start;await flow.updateComplete;const scene=flow.scene,boxes=[...scene.nodes];let collisions=0,diagonal=0,samples=0;for(const edge of scene.edges)for(const points of edge.sections)for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];if(Math.abs(a.x-b.x)>1e-6&&Math.abs(a.y-b.y)>1e-6)diagonal++;for(const [id,box]of boxes){if(id===edge.source||id===edge.target)continue;if(Math.abs(a.x-b.x)<1e-6&&a.x>box.x+.01&&a.x<box.x+box.width-.01&&Math.max(a.y,b.y)>box.y+.01&&Math.min(a.y,b.y)<box.y+box.height-.01)collisions++;if(Math.abs(a.y-b.y)<1e-6&&a.y>box.y+.01&&a.y<box.y+box.height-.01&&Math.max(a.x,b.x)>box.x+.01&&Math.min(a.x,b.x)<box.x+box.width-.01)collisions++}}for(const path of flow.shadowRoot.querySelectorAll('[part=edge]')){const length=path.getTotalLength();for(let n=0;n<=50;n++){const point=path.getPointAtLength(length*n/50);samples++;if(!Number.isFinite(point.x)||!Number.isFinite(point.y))throw new Error('Invalid path')}}return {count,layoutMs,verificationMs:performance.now()-start,ticks,collisions,diagonal,samples,nodes:scene.nodes.size,edges:scene.edges.length,workerOwned:!!flow.engine.engine}},count);assert.equal(result.nodes,count);assert.equal(result.collisions,0);assert.equal(result.diagonal,0);assert.ok(result.ticks>0);assert.equal(result.workerOwned,true);measurements.push(result)}checks.push({name:'stress measurements',pass:true,measurements})});
await check('keyboard focus brings offscreen node controls into the canvas without native scroll drift',async()=>{await page.evaluate(()=>{window.flow.panTo({x:-5000,y:-5000})});await page.waitForTimeout(30);await page.locator('#draft').focus();await page.waitForTimeout(60);const result=await page.evaluate(()=>{const viewport=window.flow.shadowRoot.querySelector('[part=viewport]'),a=viewport.getBoundingClientRect(),b=document.querySelector('#draft').getBoundingClientRect();return {scroll:[viewport.scrollLeft,viewport.scrollTop],inside:b.left>=a.left&&b.right<=a.right&&b.top>=a.top&&b.bottom<=a.bottom}});assert.deepEqual(result.scroll,[0,0]);assert.equal(result.inside,true)});

await check('owned hierarchy, one focus entry and keyboard expansion',async()=>{assert.equal(await page.locator('[role=treeitem]').count(),5);assert.equal(await page.locator('[role=treeitem][tabindex="0"]').count(),1);await page.locator('[role=treeitem][data-path=""]').focus();await page.keyboard.press('ArrowDown');await page.keyboard.press('ArrowRight');await page.waitForFunction(()=>window.events.length===1);assert.ok(await page.locator('[data-path="/alpha"] > [role=group] > [data-path="/alpha/leaf"]').count());await page.keyboard.press('ArrowRight');assert.equal(await page.locator('[data-path="/alpha/leaf"]').evaluate(el=>el===el.getRootNode().activeElement),true);await page.keyboard.press('ArrowLeft');assert.equal(await page.locator('[data-path="/alpha"]').evaluate(el=>el===el.getRootNode().activeElement),true)});
