await check('pointer cancellation retains live edits without a commit',async()=>{await page.evaluate(()=>{window.commits=0;document.querySelector('#root').addEventListener('acme-change',()=>window.commits++);document.addEventListener('pointerdown',e=>window.pointer=e.pointerId,{capture:true,once:true})});const b=await page.getByRole('separator').boundingBox();await page.mouse.move(b.x+b.width/2,b.y+30);await page.mouse.down();await page.mouse.move(b.x+b.width/2+30,b.y+30);const live=await page.locator('#root').evaluate(el=>el.sizes);await page.getByRole('separator').evaluate(el=>el.dispatchEvent(new PointerEvent('pointercancel',{pointerId:window.pointer})));await page.mouse.move(b.x+b.width/2+80,b.y+30);await page.mouse.up();assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),live);assert.equal(await page.evaluate(()=>window.commits),0);});
