await check('Home End and Shift arrows retain their percentage meanings',async()=>{await page.getByRole('separator').focus();await page.keyboard.press('Home');assert.equal(await page.locator('#navigation').evaluate(el=>el.collapsed),true);await page.keyboard.press('End');assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),[90,10]);await page.keyboard.press('Shift+ArrowLeft');assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),[80,20]);});
