await check('impossible constraints disable resizing and recover after correction',async()=>{await page.locator('#root').evaluate(async el=>{el.querySelector('#navigation').minSize=80;el.querySelector('#content').minSize=80;await el.updateComplete});assert.equal(await page.getByRole('separator').getAttribute('aria-disabled'),'true');assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),[30,70]);const range=await page.getByRole('separator').evaluate(el=>[Number(el.getAttribute('aria-valuemin')),Number(el.getAttribute('aria-valuenow')),Number(el.getAttribute('aria-valuemax'))]);assert.ok(range[0]<=range[1]&&range[1]<=range[2]);await page.locator('#root').evaluate(async el=>{el.querySelector('#navigation').minSize=10;el.querySelector('#content').minSize=10;await el.updateComplete});await page.waitForFunction(()=>document.querySelector('#handle').shadowRoot.querySelector('[role=separator]').getAttribute('aria-disabled')==='false');});
await check('a resized container cancels drag without changing keyed shares',async()=>{const box=await page.getByRole('separator').boundingBox();await page.mouse.move(box.x+4,box.y+30);await page.mouse.down();await page.locator('#root').evaluate(el=>el.style.width='400px');await page.waitForFunction(()=>!document.querySelector('#root').shadowRoot.querySelector('[part=root]').hasAttribute('data-resizing'));await page.mouse.up();assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),[30,70]);});
await check('nested resizable layouts keep independent keyed state',async()=>{await page.locator('#content').evaluate(el=>el.innerHTML='<acme-resizable id="nested" orientation="vertical" sizes="[40,60]" style="height:100%"><acme-resizable-panel value="navigation" aria-label="Nested top">Top</acme-resizable-panel><acme-resize-handle id="nested-handle"></acme-resize-handle><acme-resizable-panel value="content">Bottom</acme-resizable-panel></acme-resizable>');await page.waitForFunction(()=>document.querySelector('#nested-handle').shadowRoot?.querySelector('[role=separator]')?.getAttribute('aria-disabled')==='false');await page.locator('#nested-handle').getByRole('separator').focus();await page.keyboard.press('ArrowDown');assert.deepEqual(await page.locator('#nested').evaluate(el=>el.sizes),[41,59]);assert.deepEqual(await page.locator('#root').evaluate(el=>el.sizes),[30,70]);});
await check('Scroll Area remains the native scroll owner inside a resized pane',async()=>{await page.locator('#content').evaluate(el=>el.innerHTML='<acme-scroll-area id="scroll" orientation="vertical" style="height:100%"><acme-scroll-viewport aria-label="Scrollable editor"><div style="height:1000px">Long content</div></acme-scroll-viewport></acme-scroll-area>');await page.waitForFunction(()=>document.querySelector('#scroll').getViewport?.()?.clientHeight===240);await page.locator('#root').evaluate(el=>el.sizes=[50,50]);await page.locator('#scroll').evaluate(el=>el.scrollTo({top:300}));assert.equal(await page.locator('#scroll').evaluate(el=>el.getViewport().scrollTop),300);});
await check('collapse animation stays bounded and leaves an unrelated pane fixed',async()=>{await page.emulateMedia({reducedMotion:'no-preference'});await page.locator('#root').evaluate(async el=>{const handle=document.createElement('acme-resize-handle'),pane=document.createElement('acme-resizable-panel');pane.value='third';pane.id='third';el.append(handle,pane);await el.updateComplete;el.sizes=[30,40,30];await el.updateComplete;await Promise.all([...el.querySelectorAll('acme-resizable-panel')].map(p=>p.updateComplete));});const frames=await page.locator('#root').evaluate(async el=>{const third=el.querySelector('#third'),start=third.getBoundingClientRect().width;el.collapse('navigation');const frames=[];for(let frame=0;frame<40;frame++){await new Promise(requestAnimationFrame);frames.push({third:third.getBoundingClientRect().width-start,first:el.querySelector('#navigation').getBoundingClientRect().width});}return frames;});assert.ok(frames.every(f=>f.first>=0&&f.first<=176.3));assert.ok(frames.every(f=>Math.abs(f.third)<1));await page.emulateMedia({reducedMotion:'reduce'});});
await check('adoption releases the old document drag listener',async()=>{await page.evaluate(()=>{const add=document.addEventListener,remove=document.removeEventListener;window.visibilityListeners=new Set();document.addEventListener=function(type,listener,...args){if(type==='visibilitychange')window.visibilityListeners.add(listener);return add.call(this,type,listener,...args)};document.removeEventListener=function(type,listener,...args){if(type==='visibilitychange')window.visibilityListeners.delete(listener);return remove.call(this,type,listener,...args)}});const box=await page.getByRole('separator').boundingBox();await page.mouse.move(box.x+4,box.y+30);await page.mouse.down();assert.equal(await page.evaluate(()=>window.visibilityListeners.size),1);await page.locator('#root').evaluate(el=>{const frame=document.createElement('iframe');frame.id='adoption';document.body.append(frame);frame.contentDocument.body.append(el)});await page.mouse.up();assert.equal(await page.evaluate(()=>window.visibilityListeners.size),0);assert.deepEqual(await page.frameLocator('#adoption').locator('#root').evaluate(el=>el.sizes),[30,70]);});
