await check('native terms and definitions retain zero and authored units',async()=>{assert.equal(await page.locator('#stat dl').count(),1);assert.equal(await page.locator('#stat dt').count(),1);assert.equal(await page.locator('#number [part=root]').textContent(),'0');if(engine==='chromium'){const client=await page.context().newCDPSession(page);const ax=await client.send('Accessibility.getFullAXTree');assert.ok(ax.nodes.some(node=>!node.ignored&&node.role?.value==='DescriptionList'));assert.ok(ax.nodes.some(node=>!node.ignored&&node.role?.value==='term'&&node.name?.value.toLowerCase()==='failed deliveries'));assert.ok(ax.nodes.some(node=>!node.ignored&&node.role?.value==='definition'));await client.detach();}});
await check('direction and favorable meaning are separate and both have readable text',async()=>{assert.equal(await page.locator('#change [part=change]').getAttribute('data-sentiment'),'positive');assert.equal(await page.locator('#change acme-arrow-downward-icon').count(),1);assert.equal(await page.locator('#change .sr').textContent(),'Down, Favorable: ');await page.locator('#change').evaluate(el=>el.sentiment='negative');assert.equal(await page.locator('#change acme-arrow-downward-icon').count(),1);await page.waitForFunction(()=>document.querySelector('#change').shadowRoot.querySelector('.sr').textContent==='Down, Unfavorable: ');});
await check('loading masks data and change text without replacing author nodes',async()=>{await page.locator('#stat').evaluate(el=>{window.original=el.querySelector('#number');el.loading=true});await page.waitForFunction(()=>document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);assert.equal(await page.locator('#change dd').isVisible(),false);assert.equal(await page.locator('#number').isVisible(),false);await page.locator('#stat').evaluate(el=>el.loading=false);await page.waitForFunction(()=>!document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);assert.equal(await page.evaluate(()=>window.original===document.querySelector('#number')),true);assert.equal(await page.locator('#number [part=root]').textContent(),'0');});
await check('parts follow their new Stat owner after moving and reconnecting',async()=>{await page.locator('#value').evaluate(el=>document.querySelector('#other').append(el));await page.waitForFunction(()=>document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);await page.locator('#value').evaluate(el=>document.querySelector('#stat').append(el));await page.waitForFunction(()=>!document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);});
await check('all sizes and long labels wrap in narrow RTL layouts',async()=>{await page.setViewportSize({width:360,height:700});await page.evaluate(()=>document.documentElement.dir='rtl');await page.locator('acme-stat-label').first().evaluate(el=>el.textContent='A longer measurement label for delivery reliability');const sizes=[];for(const size of ['small','medium','large']){await page.locator('#stat').evaluate((el,size)=>{el.size=size;return el.updateComplete},size);sizes.push(await page.locator('#value dd').evaluate(el=>parseFloat(getComputedStyle(el).fontSize)));assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);}assert.ok(sizes[0]<sizes[1]&&sizes[1]<sizes[2]);await page.screenshot({path:dir+'/'+engine+'-stat.png'});});
await check('optional numeric formatting preserves application options and never invents direction',async()=>{await page.locator('#change').evaluate(el=>{el.replaceChildren();el.direction=undefined;el.value=.125;el.formatOptions={style:'percent',maximumFractionDigits:1}});await page.waitForFunction(()=>document.querySelector('#change').shadowRoot.querySelector('acme-format-number')?.shadowRoot?.textContent.includes('12.5%'));assert.equal(await page.locator('#change [part=indicator]').textContent(),'');assert.equal(await page.locator('#change').evaluate(el=>el.value),.125);});
await check('forwarded slot changes refresh the loading owner without moving the value node',async()=>{await page.evaluate(()=>{const bridge=document.createElement('div');bridge.id='bridge';bridge.attachShadow({mode:'open'}).innerHTML='<acme-stat id="ready"><slot name="ready"></slot></acme-stat><acme-stat id="busy" loading><slot name="busy"></slot></acme-stat>';const value=document.querySelector('#value');value.slot='ready';bridge.append(value);document.body.append(bridge);window.originalValue=value;});await page.waitForFunction(()=>!document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);await page.locator('#value').evaluate(el=>el.slot='busy');await page.waitForFunction(()=>document.querySelector('#value').shadowRoot.querySelector('acme-skeleton').loading);assert.equal(await page.evaluate(()=>window.originalValue===document.querySelector('#value')),true);});

await check('Steps exposes named tabs and linked retained panels',async()=>{assert.equal(await page.getByRole('tablist',{name:'Setup'}).count(),1);assert.equal(await page.getByRole('tab').count(),3);assert.equal(await page.getByRole('tab',{name:'Account',exact:true}).getAttribute('aria-selected'),'true');assert.equal(await page.locator('#account').isVisible(),true);assert.equal(await page.locator('#billing').isVisible(),false);assert.equal(await page.locator('acme-step-trigger').first().evaluate(el=>el.shadowRoot.querySelector('button').ariaControlsElements[0]===document.querySelector('acme-step-content')),true);});
await check('manual arrow navigation has one entry and does not advance',async()=>{await page.getByRole('tab',{name:'Account',exact:true}).focus();await page.keyboard.press('ArrowRight');assert.equal(await page.getByRole('tab',{name:'Billing',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);assert.equal(await page.locator('#steps').evaluate(el=>el.value),0);await page.keyboard.press('Enter');assert.equal(await page.locator('#steps').evaluate(el=>el.value),1);assert.equal(await page.locator('acme-step-trigger button[tabindex="0"]').count(),1);});
await check('RTL and vertical keys follow the current orientation',async()=>{await page.locator('#steps').evaluate(el=>el.dir='rtl');await page.getByRole('tab',{name:'Account',exact:true}).focus();await page.keyboard.press('ArrowLeft');assert.equal(await page.getByRole('tab',{name:'Billing',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);await page.locator('#steps').evaluate(el=>el.orientation='vertical');await page.keyboard.press('ArrowDown');assert.equal(await page.getByRole('tab',{name:'Confirm',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);});
await check('cancelable validation keeps the current panel and application can resume silently',async()=>{await page.locator('#steps').evaluate(el=>{window.changes=0;el.addEventListener('acme-change',()=>window.changes++);el.addEventListener('acme-request',e=>e.preventDefault())});await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),0);await page.locator('#steps').evaluate(el=>el.value=1);await page.locator('#billing').waitFor({state:'visible'});assert.equal(await page.evaluate(()=>window.changes),0);});
await check('linear progression and explicit completion keep a usable focus destination',async()=>{await page.locator('#steps').evaluate(el=>el.linear=true);await page.getByRole('tab',{name:'Confirm',exact:true}).click({force:true});assert.equal(await page.locator('#steps').evaluate(el=>el.value),0);await page.getByRole('button',{name:'Next',exact:true}).focus();for(let i=0;i<3;i++)await page.keyboard.press('Enter');assert.equal(await page.locator('#steps').evaluate(el=>el.completed&&el.value===3),true);assert.equal(await page.getByRole('button',{name:'Next',exact:true}).isDisabled(),true);await page.waitForFunction(()=>document.querySelector('acme-steps').shadowRoot.activeElement?.getAttribute('part')==='completed');await page.getByRole('button',{name:'Previous',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),2);});
await check('disabled steps are skipped by progression and keyboard',async()=>{await page.locator('acme-step').nth(1).evaluate(el=>el.disabled=true);await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),2);await page.getByRole('tab',{name:'Confirm',exact:true}).focus();await page.keyboard.press('Home');assert.equal(await page.getByRole('tab',{name:'Account',exact:true}).evaluate(el=>el.getRootNode().activeElement===el),true);});
await check('panel input identity is preserved and focused content recovers on a programmatic move',async()=>{await page.locator('#account').fill('Edited');await page.locator('#steps').evaluate(el=>el.value=1);await page.waitForFunction(()=>document.querySelectorAll('acme-step-trigger')[1].shadowRoot.activeElement?.localName==='button');await page.locator('#steps').evaluate(el=>el.value=0);assert.equal(await page.locator('#account').inputValue(),'Edited');});
await check('Timeline is an ordered list without a selection owner',async()=>{const list=page.getByRole('list',{name:'Delivery'});assert.equal(await list.count(),1);assert.equal(await page.locator('acme-timeline-item li').count(),2);assert.equal(await page.locator('acme-timeline-item [part=connector]').last().evaluate(el=>el.hidden),true);assert.equal(await page.locator('acme-timeline [role=tab]').count(),0);});
await check('Timeline changes orientation and final connector without replacing content',async()=>{await page.locator('acme-timeline').evaluate(el=>{window.time=el.querySelector('time');el.orientation='horizontal';el.append(el.firstElementChild)});await page.waitForFunction(()=>document.querySelector('acme-timeline-item').shadowRoot.querySelector('li').dataset.orientation==='horizontal');assert.equal(await page.locator('acme-timeline-item').last().evaluate(el=>el.querySelector('time')===window.time),true);assert.equal(await page.locator('acme-timeline-item [part=connector]').last().evaluate(el=>el.hidden),true);});
await check('reordered steps derive indexes and reconnect without duplicate changes',async()=>{await page.locator('#steps').evaluate(el=>{window.changes=0;el.addEventListener('acme-change',()=>window.changes++);el.prepend(el.querySelectorAll('acme-step')[2]);el.remove();document.body.prepend(el)});await page.getByRole('tab',{name:'Confirm',exact:true}).waitFor();await page.waitForFunction(()=>document.querySelector('acme-step-trigger').shadowRoot.querySelector('button').getAttribute('aria-selected')==='true');await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.evaluate(()=>window.changes),1);assert.equal(await page.getByRole('tab',{name:'Account',exact:true}).getAttribute('aria-selected'),'true');});
await check('duplicate values block ambiguous navigation and recover after correction',async()=>{await page.locator('acme-step').nth(1).evaluate(el=>el.value='account');await page.waitForFunction(()=>document.querySelectorAll('acme-step-trigger')[0].shadowRoot.querySelector('button').disabled);await page.locator('acme-step').nth(1).evaluate(el=>el.value='billing');await page.waitForFunction(()=>!document.querySelectorAll('acme-step-trigger')[0].shadowRoot.querySelector('button').disabled);});
await check('native form validation can cancel and then permit a forward request',async()=>{await page.locator('#steps').evaluate(el=>{const panel=el.querySelector('acme-step-content');const form=document.createElement('form');form.id='validation';form.innerHTML='<input id="required" required>';panel.append(form);el.addEventListener('acme-request',e=>{if(e.detail.value>e.detail.previousValue&&!form.reportValidity())e.preventDefault()})});await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),0);await page.locator('#required').fill('Ready');await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),1);});
await check('controlled request overrides stay authoritative and silent',async()=>{await page.locator('#steps').evaluate(el=>{window.changes=0;el.addEventListener('acme-change',()=>window.changes++);el.addEventListener('acme-request',()=>el.value=2)});await page.getByRole('button',{name:'Next',exact:true}).click();assert.equal(await page.locator('#steps').evaluate(el=>el.value),2);assert.equal(await page.evaluate(()=>window.changes),0);});
await check('keyboard focus and narrow layout remain visible',async()=>{await page.setViewportSize({width:360,height:640});await page.getByRole('tab',{name:'Account',exact:true}).focus();assert.equal(await page.getByRole('tab',{name:'Account',exact:true}).evaluate(el=>getComputedStyle(el).outlineStyle),'solid');assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth),true);});
await check('pointer focus follows the bare native button baseline',async()=>{await page.evaluate(()=>{const bare=document.createElement('button');bare.id='bare';bare.textContent='Bare';document.body.append(bare)});await page.locator('#bare').focus();await page.locator('#bare').click();const native=await page.locator('#bare').evaluate(el=>document.activeElement===el);const next=page.getByRole('button',{name:'Next',exact:true});await next.focus();await next.click();const actual=await next.evaluate(el=>el.getRootNode().activeElement===el);assert.equal(actual,native);});
await check('removed numeric and orientation attributes restore defaults',async()=>{await page.locator('#steps').evaluate(el=>{el.setAttribute('value','2');el.setAttribute('orientation','vertical');el.removeAttribute('value');el.removeAttribute('orientation')});assert.deepEqual(await page.locator('#steps').evaluate(el=>[el.value,el.orientation]),[0,'horizontal']);});

await check('Table preserves author-owned native content and direct references',async()=>{await page.getByRole('button',{name:'Retry delivery'}).click();assert.equal(await page.evaluate(()=>window.table.getTableElement()===window.nativeTable),true);assert.equal(await page.evaluate(()=>window.row.parentElement===window.nativeTable.tBodies[0]),true);assert.deepEqual(await page.evaluate(()=>window.events),['retry']);assert.equal(await page.evaluate(()=>window.table.getScrollElement().getAttribute('part')),'viewport');});
await check('native caption, headers and cells survive the shadow scrolling box',async()=>{if(engine==='chromium'){const client=await page.context().newCDPSession(page),ax=await client.send('Accessibility.getFullAXTree');assert.ok(ax.nodes.some(n=>!n.ignored&&n.role?.value==='table'&&n.name?.value==='Deliveries'));assert.ok(ax.nodes.some(n=>!n.ignored&&n.role?.value==='rowheader'&&n.name?.value==='Order created'));await client.detach();}assert.equal(await page.locator('#table > table').evaluate(el=>getComputedStyle(el).fontSize),'14px');});
await check('variant, density and size affect the native cells without changing author state',async()=>{const cell=page.locator('#table > table > tbody > tr > td');assert.equal(await cell.evaluate(el=>getComputedStyle(el).paddingBlockStart),'10px');await page.evaluate(()=>{const theme=document.createElement('acme-theme');theme.density='compact';window.table.before(theme);theme.append(window.table)});await page.waitForFunction(()=>getComputedStyle(window.table.querySelector('td')).paddingBlockStart==='5px');await page.evaluate(()=>{window.table.variant='striped';window.table.size='small'});assert.ok(await cell.evaluate(el=>parseFloat(getComputedStyle(el).paddingBlockStart)<5));await page.evaluate(()=>window.table.size='large');assert.equal(await cell.evaluate(el=>getComputedStyle(el).fontSize),'16px');assert.equal(await page.evaluate(()=>window.table.getTableElement()===window.nativeTable),true);});
await check('light styles follow a table into another shadow root and do not style unrelated tables',async()=>{await page.evaluate(()=>{const sibling=document.createElement('table');sibling.id='plain';sibling.innerHTML='<tbody><tr><td>Plain</td></tr></tbody>';document.body.append(sibling);const host=document.createElement('div');document.body.append(host);host.attachShadow({mode:'open'}).append(window.table)});assert.equal(await page.locator('#table td').evaluate(el=>getComputedStyle(el).paddingBlockStart),'10px');assert.notEqual(await page.locator('#plain td').evaluate(el=>getComputedStyle(el).paddingBlockStart),'10px');});
await check('sticky headers and logical column pins retain geometry during two-axis scroll in RTL',async()=>{await page.evaluate(()=>{document.documentElement.dir='rtl';window.table.stickyHeader=true;window.table.style.cssText='width:400px;height:200px';window.nativeTable.style.cssText='width:900px;table-layout:fixed';const head=window.nativeTable.querySelector('th');head.dataset.pinned='start';head.style.width='160px';window.nativeTable.tBodies[0].innerHTML=Array.from({length:30},(_,i)=>'<tr><th scope="row" data-pinned="start">Endpoint '+i+'</th><td>Delivered '+i+'</td></tr>').join('')});await page.evaluate(()=>window.table.getScrollElement().scrollTop=80);await page.waitForTimeout(100);const header=page.locator('#table > table > thead th').first(),before=await header.boundingBox();await page.evaluate(()=>{const viewport=window.table.getScrollElement();viewport.scrollTop=300;viewport.scrollLeft=-300});await page.waitForTimeout(100);const after=await header.boundingBox();assert.ok(Math.abs(after.y-before.y)<1);assert.ok(Math.abs(after.x-before.x)<1);assert.equal(await page.evaluate(()=>window.table.getScrollElement().tabIndex),0);});
await check('native spans, grouped headings and footer markup remain application-owned',async()=>{await page.evaluate(()=>{window.nativeTable.innerHTML='<caption>Grouped deliveries</caption><thead><tr><th colspan="2">Delivery</th><th rowspan="2">Result</th></tr><tr><th>ID</th><th>Endpoint</th></tr></thead><tbody><tr><th rowspan="2">1</th><td>A</td><td>Done</td></tr><tr><td colspan="2">Expanded details</td></tr></tbody><tfoot><tr><th colspan="2">Total</th><td>2</td></tr></tfoot>'});assert.equal(await page.locator('#table [colspan="2"]').count(),3);assert.equal(await page.locator('#table [rowspan="2"]').count(),2);assert.equal(await page.locator('#table > table').evaluate(el=>el.rows.length),5);});
await check('loading changes only busy presentation and never disables or discards content',async()=>{await page.evaluate(()=>window.table.loading=true);assert.equal(await page.evaluate(()=>window.table.getScrollElement().getAttribute('aria-busy')),'true');await page.getByRole('button',{name:'Retry delivery'}).click();assert.deepEqual(await page.evaluate(()=>window.events),['retry']);assert.equal(await page.evaluate(()=>window.row.isConnected),true);});
await check('cell range outlines do not change row or column geometry',async()=>{const cell=page.locator('#table td');const before=await cell.boundingBox();await cell.evaluate(el=>{el.setAttribute('data-range-top','');el.setAttribute('data-range-bottom','');el.setAttribute('data-range-start','');el.setAttribute('data-range-end','')});const after=await cell.boundingBox();assert.equal(after.height,before.height);assert.equal(after.width,before.width);});
await check('fallback rendering is distinct from authored content in real slot assignment',async()=>{await page.evaluate(()=>document.body.append(document.createElement('places-fallback-check')));await page.locator('places-fallback-check span').waitFor();assert.equal(await page.locator('places-fallback-check').evaluate(el=>el.places.has('')),false);});
await check('nested tables do not inherit outer row selection or range decoration',async()=>{await page.locator('#table td').evaluate(el=>el.innerHTML='<acme-table id="nested"><table><tbody><tr><td>Nested</td></tr></tbody></table></acme-table>');const nested=page.locator('#nested td');await nested.waitFor();const before=await nested.evaluate(el=>({background:getComputedStyle(el).backgroundColor,shadow:getComputedStyle(el).boxShadow}));await page.locator('#row').evaluate(el=>{el.setAttribute('aria-selected','true');el.querySelector('td').setAttribute('data-range-top','')});const after=await nested.evaluate(el=>({background:getComputedStyle(el).backgroundColor,shadow:getComputedStyle(el).boxShadow}));assert.deepEqual(after,before);});

